-- Athena saved query (Product_B2C_Intl)
-- ID: fe9fdc1f-58f9-43b0-9a21-e03d4ad3afea
-- Name: SameDay vs Same hour bookings - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH target_routes AS ( SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (733, 807), (462, 130), (807, 733), (313, 979), (979, 313), (130, 444), (309, 130), (130, 571), (122, 602), (602, 122), (141, 126), (646, 130), (74706, 74820), (126, 141), (233, 123), (551, 472), (571, 130), (733, 1290), (551, 473), (473, 551), (1290, 733), (122, 129), (472, 551), (130, 79546), (71929, 141), (124, 125), (90883, 74701), (470, 551), (236, 122), (74701, 90883), (125, 124), (1443, 807), (807, 70015), (807, 1443), (313, 1001), (71756, 123), (807, 1290), (129, 122), (313, 94152), (467, 123), (979, 1001), (244, 122), (123, 467), (1001, 313), (293, 122), (443, 979), (979, 443), (455, 123), (1001, 81826), (1001, 979), (123, 455), (141, 216), (94152, 313), (602, 141), (201668, 74706), (443, 70024), (70024, 83760), (1290, 70015) ) AS t(s, d) ), base_data AS ( /* Pre-calculating IST timestamps to make the final SELECT cleaner */ SELECT UPPER(t.user_type) AS user_type, CASE WHEN t.sales_channel = 'RB:MOBILEWEB#droidapp' THEN 'Android' WHEN t.sales_channel = 'RB:MOBILEWEB#iosapp' THEN 'iOS' WHEN t.sales_channel = 'WEBDIRECT' THEN 'Desktop' WHEN t.sales_channel = 'MOBILEWEB' THEN 'MobWeb' END AS sales_channel, CASE WHEN t.is_ac = True THEN 'AC' WHEN t.is_ac = False THEN 'non-AC' END AS is_ac, t.tin, DATE_ADD('minute', 330, t.date_of_issue) as issue_ist, DATE_ADD('minute', 330, t.date_of_journey) as journey_ist FROM "transaction"."bus_ticket_events" t INNER JOIN target_routes tr ON t.source_location_id = tr.src_id AND t.destination_location_id = tr.dest_id WHERE t.time_of_event >= TIMESTAMP '2025-12-31 18:30:00' AND t.time_of_event < TIMESTAMP '2026-01-31 18:30:00' AND t.country_code = 'IND' AND t.event_class = 2 AND t.event_type = 101 AND business_unit IN ('REDBUS_IN') AND sales_channel IN ('RB:MOBILEWEB#droidapp', 'RB:MOBILEWEB#iosapp', 'WEBDIRECT', 'MOBILEWEB') ) SELECT user_type, sales_channel, is_ac, COUNT(DISTINCT tin) as total_txn_count, /* Same Day: Cast to DATE to compare just the calendar day */ COUNT(DISTINCT CASE WHEN DATE(issue_ist) = DATE(journey_ist) THEN tin END) AS same_day_txn_count, /* Same Hour: Keep as TIMESTAMP to calculate hours difference */ COUNT(DISTINCT CASE WHEN DATE_DIFF('hour', issue_ist, journey_ist) = 0 THEN tin END) AS same_hour_txn_count FROM base_data GROUP BY user_type, sales_channel, is_ac
